#!/usr/bin/env python3
"""Count lines, words and characters in text files and print an aligned table."""

import json
import os
import sys

PROG = "wordcount.py"


def count_text(text):
    chars = len(text)
    words = len(text.split())
    lines = text.count("\n")
    if text and not text.endswith("\n"):
        lines += 1
    return lines, words, chars


def count_file(path):
    with open(path, "rb") as f:
        data = f.read()
    return count_text(data.decode("utf-8"))


def count_stdin():
    data = sys.stdin.buffer.read()
    return count_text(data.decode("utf-8"))


def main(argv):
    paths = [a for a in argv[1:] if a != "--json"]
    as_json = "--json" in argv[1:]
    if not paths:
        print(f"usage: {PROG} [--json] FILE [FILE ...]", file=sys.stderr)
        return 2

    rows = []
    failed = False
    for path in paths:
        try:
            if path == "-":
                counts = count_stdin()
            else:
                if not os.path.isfile(path):
                    raise OSError
                counts = count_file(path)
            rows.append((path,) + counts)
        except (OSError, UnicodeDecodeError):
            print(f"{PROG}: cannot read {path}", file=sys.stderr)
            failed = True

    if as_json:
        files = [
            {"file": p, "lines": l, "words": w, "chars": c} for p, l, w, c in rows
        ]
        total = {
            "lines": sum(r[1] for r in rows),
            "words": sum(r[2] for r in rows),
            "chars": sum(r[3] for r in rows),
        }
        json.dump({"files": files, "total": total}, sys.stdout)
        sys.stdout.write("\n")
    elif rows:
        headers = ("lines", "words", "chars", "file")
        table = [(str(l), str(w), str(c), p) for p, l, w, c in rows]
        if len(rows) > 1:
            total = (
                sum(r[1] for r in rows),
                sum(r[2] for r in rows),
                sum(r[3] for r in rows),
            )
            table.append((str(total[0]), str(total[1]), str(total[2]), "total"))

        widths = [
            max(len(headers[i]), *(len(row[i]) for row in table)) for i in range(3)
        ]
        lines_out = []
        fmt = f"{{:>{widths[0]}}}  {{:>{widths[1]}}}  {{:>{widths[2]}}}  {{}}"
        lines_out.append(fmt.format(*headers))
        for row in table:
            lines_out.append(fmt.format(*row))
        sys.stdout.write("\n".join(lines_out) + "\n")

    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
