#!/usr/bin/env python3
"""Count lines, words and characters in text files and print an aligned table."""

import io
import json
import os
import sys

PROG = "wordcount.py"


def count_text(data):
    chars = len(data)
    words = len(data.split())
    lines = data.count("\n")
    if data and not data.endswith("\n"):
        lines += 1
    return lines, words, chars


def count_path(path):
    if path == "-":
        stream = io.TextIOWrapper(
            sys.stdin.buffer, encoding="utf-8", newline=""
        )
        try:
            data = stream.read()
        finally:
            stream.detach()
        return count_text(data)
    with open(path, "r", encoding="utf-8", newline="") as f:
        return count_text(f.read())


def main(argv):
    args = argv[1:]
    as_json = "--json" in args
    paths = [a for a in args if a != "--json"]
    if not paths:
        print(f"usage: {PROG} FILE [FILE ...]", file=sys.stderr)
        return 2

    rows = []
    had_error = False
    for path in paths:
        try:
            if path != "-" and not os.path.isfile(path):
                raise OSError
            rows.append((path,) + count_path(path))
        except OSError:
            print(f"{PROG}: cannot read {path}", file=sys.stderr)
            had_error = True

    if as_json:
        files = [
            {"file": path, "lines": n, "words": w, "chars": c}
            for path, n, w, c in rows
        ]
        total = {
            "lines": sum(r[1] for r in rows),
            "words": sum(r[2] for r in rows),
            "chars": sum(r[3] for r in rows),
        }
        json.dump({"files": files, "total": total}, sys.stdout)
        sys.stdout.write("\n")
    elif rows:
        header = ("lines", "words", "chars", "file")
        all_rows = [header] + [
            (str(n), str(w), str(c), path) for path, n, w, c in rows
        ]
        if len(rows) > 1:
            total = [sum(v) for v in zip(*(r[1:] for r in rows))]
            all_rows.append(
                (str(total[0]), str(total[1]), str(total[2]), "total")
            )
        widths = [
            max(len(row[i]) for row in all_rows) for i in range(3)
        ]
        out = []
        for row in all_rows:
            cells = [row[i].rjust(widths[i]) for i in range(3)]
            cells.append(row[3])
            out.append("  ".join(cells))
        sys.stdout.write("\n".join(out) + "\n")

    return 1 if had_error else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
