#!/usr/bin/env python3
"""Print lines of a log file at a given level."""

import argparse
import os
import stat
import sys

LEVELS = ["INFO", "WARN", "ERROR"]
RANK = {name: i for i, name in enumerate(LEVELS)}


class UsageError(Exception):
    pass


def build_parser():
    parser = argparse.ArgumentParser(
        prog="logscan.py",
        description="Print the lines of a log file at a given level.",
        exit_on_error=False,
    )
    parser.add_argument("path", metavar="PATH")
    parser.add_argument("level", metavar="LEVEL")
    parser.add_argument("--at-least", action="store_true", default=False)
    parser.add_argument("--limit", default=None)
    return parser


def parse_args(argv):
    parser = build_parser()
    try:
        args = parser.parse_args(argv)
    except argparse.ArgumentError as exc:
        raise UsageError(str(exc))

    if args.level.upper() not in RANK:
        raise UsageError("LEVEL must be one of INFO, WARN, ERROR (any case)")

    if args.limit is not None:
        try:
            limit = int(args.limit, 10)
        except ValueError:
            raise UsageError("--limit must be an integer of 0 or more")
        if limit < 0:
            raise UsageError("--limit must be an integer of 0 or more")
        args.limit = limit

    return args


def line_level(line):
    fields = line.split()
    if len(fields) < 3:
        return None
    level = fields[2]
    return level if level in RANK else None


def run(path, level, at_least, limit):
    try:
        st = os.stat(path)
    except OSError:
        st = None
    if st is None or not stat.S_ISREG(st.st_mode):
        print(f"logscan.py: cannot open {path}", file=sys.stderr)
        return 1
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
        try:
            content = raw.decode("utf-8")
        except UnicodeDecodeError:
            print(f"logscan.py: cannot open {path}", file=sys.stderr)
            return 1
    except OSError:
        print(f"logscan.py: cannot open {path}", file=sys.stderr)
        return 1

    lines = content.split("\n")
    if lines and lines[-1] == "":
        lines.pop()

    target = RANK[level.upper()]
    count = 0
    printed = 0
    for line in lines:
        lvl = line_level(line)
        if lvl is None:
            continue
        rank = RANK[lvl]
        if rank == target or (at_least and rank > target):
            count += 1
            if limit is None or printed < limit:
                sys.stdout.write(line + "\n")
                printed += 1

    print(f"count={count}", file=sys.stderr)
    try:
        sys.stdout.flush()
    except BrokenPipeError:
        pass
    return 0


def main(argv):
    try:
        args = parse_args(argv)
    except UsageError as exc:
        print("usage: logscan.py PATH LEVEL [--at-least] [--limit N]", file=sys.stderr)
        print(f"logscan.py: error: {exc}", file=sys.stderr)
        return 2
    return run(args.path, args.level, args.at_least, args.limit)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
