check("exact warn stdout", r.out === "2026-03-14 09:26:54 WARN disk 91% full\n", JSON.stringify(r));
check("exact warn count", r.err === "count=1\n", JSON.stringify(r.err));
check("exact warn code", r.code === 0);

r = run([T, "WaRn"]);
