import re

__all__ = ["ParseError", "Config", "parse"]


class ParseError(ValueError):
    def __init__(self, lineno, message):
        self.lineno = lineno
        super().__init__(f"line {lineno}: {message}")


_HEADER_RE = re.compile(r"^\[([^\]]*)\]\s*$")
_KEY_RE = re.compile(r"^([^=\s][^=]*)=(.*)$")

_TRUE_WORDS = {"true", "yes", "on", "1"}
_FALSE_WORDS = {"false", "no", "off", "0"}
_INT_RE = re.compile(r"^[+-]?[0-9]+$")


class Config:
    def __init__(self):
        self._data = {}

    def sections(self):
        return list(self._data)

    def keys(self, section):
        return list(self._data[section])

    def get(self, section, key, default=None):
        sec = self._data.get(section)
        if sec is None:
            return default
        return sec.get(key, default)

    def getint(self, section, key, default=None):
        value = self.get(section, key)
        if value is None:
            return default
        if not _INT_RE.match(value):
            raise ValueError(f"invalid int value: {value!r}")
        return int(value)

    def getbool(self, section, key, default=None):
        value = self.get(section, key)
        if value is None:
            return default
        lowered = value.lower()
        if lowered in _TRUE_WORDS:
            return True
        if lowered in _FALSE_WORDS:
            return False
        raise ValueError(f"invalid bool value: {value!r}")

    def getlist(self, section, key, default=None):
        value = self.get(section, key)
        if value is None:
            return default
        return [item.strip() for item in value.split(",") if item.strip()]


def parse(text):
    config = Config()
    current_section = None
    last_key = None
    lines = text.splitlines()

    for idx, raw in enumerate(lines):
        lineno = idx + 1
        stripped = raw.strip()

        if stripped == "":
            last_key = None
            continue

        if stripped[0] in (";", "#"):
            last_key = None
            continue

        indented = raw[0] in (" ", "\t")

        if indented:
            if current_section is None or last_key is None:
                raise ParseError(lineno, "indented line is not a valid continuation")
            config._data[current_section][last_key] += "\n" + stripped
            continue

        last_key = None

        header_match = _HEADER_RE.match(raw)
        if header_match:
            name = header_match.group(1).strip()
            if not name:
                raise ParseError(lineno, "empty section name")
            if name in config._data:
                raise ParseError(lineno, f"duplicate section name: {name!r}")
            config._data[name] = {}
            current_section = name
            continue

        key_match = _KEY_RE.match(raw)
        if key_match:
            if current_section is None:
                raise ParseError(lineno, "key line before any section header")
            key = key_match.group(1).strip()
            value = key_match.group(2).strip()
            if not key:
                raise ParseError(lineno, "empty key")
            if key in config._data[current_section]:
                raise ParseError(lineno, f"duplicate key: {key!r}")
            config._data[current_section][key] = value
            last_key = key
            continue

        raise ParseError(lineno, "unrecognized line")

    return config
