import re

_INT_RE = re.compile(r"^[+-]?[0-9]+$")

_TRUE_WORDS = {"true", "yes", "on", "1"}
_FALSE_WORDS = {"false", "no", "off", "0"}


class ParseError(ValueError):
    def __init__(self, message, lineno):
        super().__init__("line %d: %s" % (lineno, message))
        self.lineno = lineno


class Config:
    def __init__(self):
        self._data = {}
        self._order = []

    def sections(self):
        return list(self._order)

    def keys(self, section):
        if section not in self._data:
            raise KeyError(section)
        return list(self._data[section].keys())

    def get(self, section, key, default=None):
        sec = self._data.get(section)
        if sec is None:
            return default
        return sec.get(key, default)

    def getint(self, section, key, default=None):
        raw = self.get(section, key)
        if raw is None:
            return default
        if not _INT_RE.match(raw):
            raise ValueError("not an integer: %r" % raw)
        return int(raw)

    def getbool(self, section, key, default=None):
        raw = self.get(section, key)
        if raw is None:
            return default
        lowered = raw.lower()
        if lowered in _TRUE_WORDS:
            return True
        if lowered in _FALSE_WORDS:
            return False
        raise ValueError("not a boolean: %r" % raw)

    def getlist(self, section, key, default=None):
        raw = self.get(section, key)
        if raw is None:
            return default
        return [item.strip() for item in raw.split(",") if item.strip()]


def parse(text):
    config = Config()
    lines = text.splitlines()
    current = None
    pending = None
    n = len(lines)
    i = 0
    while i < n:
        lineno = i + 1
        line = lines[i]
        stripped = line.strip()
        if stripped == "":
            pending = None
            i += 1
            continue
        if stripped[0] in (";", "#"):
            i += 1
            continue
        if line[:1] in (" ", "\t"):
            if pending is None:
                raise ParseError("unexpected indented line", lineno)
            config._data[current][pending] += "\n" + stripped
            i += 1
            continue
        pending = None
        if stripped.startswith("["):
            close = stripped.rfind("]")
            if close == -1:
                raise ParseError("malformed section header", lineno)
            name = stripped[1:close].strip()
            if name == "":
                raise ParseError("empty section name", lineno)
            if stripped[close + 1:].strip() != "":
                raise ParseError("trailing characters after section header", lineno)
            if name in config._data:
                raise ParseError("duplicate section: %s" % name, lineno)
            current = name
            config._data[name] = {}
            config._order.append(name)
            i += 1
            continue
        if "=" in stripped:
            if current is None:
                raise ParseError("key outside of a section", lineno)
            key, _, value = stripped.partition("=")
            key = key.strip()
            value = value.strip()
            if key == "":
                raise ParseError("empty key", lineno)
            if key in config._data[current]:
                raise ParseError("duplicate key: %s" % key, lineno)
            config._data[current][key] = value
            pending = key
            i += 1
            continue
        raise ParseError("unexpected line", lineno)
    return config
