```python
"""Semantic Versioning 2.0.0 versions and simple version ranges.

Implements the subset of the SemVer 2.0.0 specification relevant to version
numbers (parsing, canonical text, precedence comparison) plus a small
range/checker language with ``^``, ``~``, ``=``, ``>``, ``>=``, ``<`` and
``<=`` comparators.  Only the Python 3.12 standard library is used.
"""

from __future__ import annotations

import re

__all__ = ["Version", "satisfies"]

_NUM = r"0|[1-9]\d*"
_PRE_IDENT_RE = re.compile(r"(?:0|[1-9]\d*|[1-9A-Za-z][0-9A-Za-z-]*)\Z")
_BUILD_IDENT_RE = re.compile(r"(?:0|[1-9A-Za-z][0-9A-Za-z-]*)\Z")
_ALNUM_ONLY_RE = re.compile(r"[0-9A-Za-z-]+\Z")
_NUMERIC_RE = re.compile(r"\d+\Z")


def _validate(text: str, *, allow_partial: bool):
    """Validate a version core, rejecting any pre-release or build part.

    Returns ``(major, minor, patch)``; a partial version (1 or 2 numeric
    components, only when *allow_partial*) has its missing components filled
    with zero.  Raises ``ValueError`` for any malformed input.
    """
    if not text or any(c.isspace() for c in text):
        raise ValueError(f"invalid version: {text!r}")

    for sep in ("-", "+"):
        if sep in text:
            raise ValueError(f"pre-release and build parts are not allowed here: {text!r}")

    parts = text.split(".")
    if not (1 if allow_partial else 3) <= len(parts) <= 3:
        raise ValueError(f"invalid version: {text!r}")
    if not all(_NUM.match(p) for p in parts):
        raise ValueError(f"invalid numeric component in: {text!r}")
    nums = [int(p) for p in parts]
    nums += [0] * (3 - len(nums))
    return nums[0], nums[1], nums[2]


def _split_token(token: str):
    """Split a range token into ``(operator, version-part)``.

    *operator* is one of ``'', '^', '~', '=', '>', '<', '>=', '<='``.  The
    version part is validated as a (possibly partial) version; a partial
    version may not carry a pre-release or build part.
    """
    for op in (">=", "<=", "^", "~", "=", ">", "<"):
        if token.startswith(op):
            rest = token[len(op):]
            if not rest:
                raise ValueError(f"invalid comparator: {token!r}")
            _validate(rest, allow_partial=True)
            return op, rest
    _validate(token, allow_partial=True)
    return "", token


def _comparators_for(op: str, part: str):
    """Return the list of ``(operator, Version)`` pairs a token expands to."""
    if op not in ("^", "~"):
        o = "=" if op == "" else op
        return [(o, Version.parse(part))]

    major, minor, patch = _validate(part, allow_partial=True)
    n = len(part.split("."))
    lower = Version(major, minor, patch)
    if op == "^":
        if n == 1:
            upper = Version(major + 1, 0, 0)
        elif major != 0 or n == 3:
            upper = _caret_upper(major, minor, patch)
        else:
            upper = _caret_upper(minor, patch, 0)
        return [(">=", lower), ("<", upper)]

    # op == '~'
    if n == 1:
        upper = Version(major + 1, 0, 0)
    else:
        upper = Version(major, minor + 1, 0)
    return [(">=", lower), ("<", upper)]


def _caret_upper(major: int, minor: int, patch: int) -> Version:
    if major != 0:
        return Version(major + 1, 0, 0)
    if minor != 0:
        return Version(0, minor + 1, 0)
    return Version(0, 0, patch + 1)


def _cmp_ident(a: str, b: str) -> int:
    an, bn = _NUMERIC_RE.match(a), _NUMERIC_RE.match(b)
    if an and bn:
        return (int(a) > int(b)) - (int(a) < int(b))
    if an:
        return -1
    if bn:
        return 1
    return (a > b) - (a < b)


class Version:
    """An immutable Semantic Version 2.0.0 version number."""

    __slots__ = ("major", "minor", "patch", "prerelease", "build")

    def __init__(self, major: int, minor: int, patch: int,
                 prerelease: tuple[str, ...] = (), build: tuple[str, ...] = ()):
        for name, value in (("major", major), ("minor", minor), ("patch", patch)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                raise ValueError(f"{name} must be a non-negative int, got {value!r}")
        object.__setattr__(self, "major", major)
        object.__setattr__(self, "minor", minor)
        object.__setattr__(self, "patch", patch)
        object.__setattr__(self, "prerelease", tuple(prerelease))
        object.__setattr__(self, "build", tuple(build))

    def __setattr__(self, name, value):
        raise AttributeError("Version objects are immutable")

    def __delattr__(self, name):
        raise AttributeError("Version objects are immutable")

    @classmethod
    def parse(cls, text: str) -> "Version":
        """Parse a full ``MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]`` string."""
        if not isinstance(text, str):
            raise TypeError(f"expected str, got {type(text).__name__}")
        if not text or text != text.strip() or any(c.isspace() for c in text):
            raise ValueError(f"invalid version string: {text!r}")
        if text.startswith("v") or text.startswith("V"):
            raise ValueError(f"invalid version string: {text!r}")

        core, sep, build_raw = text.partition("+")
        if sep and not build_raw:
            raise ValueError("build metadata must not be empty")

        core, sep, pre_raw = core.partition("-")
        if sep and (not pre_raw or not _ALNUM_ONLY_RE.match(pre_raw)):
            raise ValueError(f"invalid pre-release: {pre_raw!r}")

        major, minor, patch = _validate(core, allow_partial=False)

        prerelease: tuple[str, ...] = ()
        if pre_raw:
            prerelease = tuple(pre_raw.split("."))
            for ident in prerelease:
                if not _PRE_IDENT_RE.match(ident):
                    raise ValueError(f"invalid pre-release identifier: {ident!r}")

        build: tuple[str, ...] = ()
        if build_raw:
            if not _ALNUM_ONLY_RE.match(build_raw):
                raise ValueError(f"invalid build metadata: {build_raw!r}")
            build = tuple(build_raw.split("."))
            for ident in build:
                if not _BUILD_IDENT_RE.match(ident):
                    raise ValueError(f"invalid build identifier: {ident!r}")

        return cls(major, minor, patch, prerelease, build)

    def __str__(self) -> str:
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text

    def __repr__(self) -> str:
        return f"Version({str(self)!r})"

    def _compare(self, other: "Version") -> int:
        core_a, core_b = (self.major, self.minor, self.patch), (other.major, other.minor, other.patch)
        if core_a != core_b:
            return (core_a > core_b) - (core_a < core_b)
        if bool(self.prerelease) != bool(other.prerelease):
            return -1 if self.prerelease else 1
        for a, b in zip(self.prerelease, other.prerelease):
            c = _cmp_ident(a, b)
            if c:
                return c
        return (len(self.prerelease) > len(other.prerelease)) - \
               (len(self.prerelease) < len(other.prerelease))

    def __lt__(self, other):
        if isinstance(other, Version):
            return self._compare(other) < 0
        return NotImplemented

    def __le__(self, other):
        if isinstance(other, Version):
            return self._compare(other) <= 0
        return NotImplemented

    def __gt__(self, other):
        if isinstance(other, Version):
            return self._compare(other) > 0
        return NotImplemented

    def __ge__(self, other):
        if isinstance(other, Version):
            return self._compare(other) >= 0
        return NotImplemented

    def __eq__(self, other):
        if isinstance(other, Version):
            return self._compare(other) == 0
        return NotImplemented

    def __ne__(self, other):
        if isinstance(other, Version):
            return self._compare(other) != 0
        return NotImplemented

    def __hash__(self) -> int:
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def bump(self, kind: str) -> "Version":
        """Return the version bumped by *kind* ('major', 'minor' or 'patch')."""
        if kind == "major":
            return Version(self.major + 1, 0, 0)
        if kind == "minor":
            return Version(self.major, self.minor + 1, 0)
        if kind == "patch":
            return Version(self.major, self.minor, self.patch + 1)
        raise ValueError(f"invalid bump kind: {kind!r}")


def _as_version(version) -> Version:
    if isinstance(version, Version):
        return version
    if isinstance(version, str):
        return Version.parse(version)
    raise TypeError(f"expected Version or str, got {type(version).__name__}")


_OPS = {
    "=": lambda c: c == 0,
    ">=": lambda c: c >= 0,
    ">": lambda c: c > 0,
    "<=": lambda c: c <= 0,
    "<": lambda c: c < 0,
}


def satisfies(version, spec: str) -> bool:
    """Return True if *version* satisfies the range *spec*."""
    v = _as_version(version)
    if not isinstance(spec, str):
        raise TypeError(f"spec must be str, got {type(spec).__name__}")
    tokens = spec.split()
    if not tokens:
        raise ValueError("version range must contain at least one comparator")

    for token in tokens:
        op, part = _split_token(token)
        for cop, cver in _comparators_for(op, part):
            if not _OPS[cop](v._compare(cver)):
                return False
    return True
