# tilde
ok &= check("~1.2.3 1.2.9", satisfies('1.2.9', '~1.2.3'), True)
ok &= check("~1.2.3 1.3.0 no", satisfies('1.3.0', '~1.2.3'), False)
ok &= check("~1.2.3 1.2.2 no", satisfies('1.2.2', '~1.2.3'), False)
ok &= check("~1.2 1.2.0", satisfies('1.2.0', '~1.2'), True)
