ok &= check("~1 1.9.9", satisfies('1.9.9', '~1'), True)
ok &= check("~1 2.0.0 no", satisfies('2.0.0', '~1'), False)
ok &= check("~1 0.9.9 no", satisfies('0.9.9', '~1'), False)

