```python
"""Semantic Versioning 2.0.0 versions and simple version ranges."""

import re

__all__ = ["Version", "satisfies"]

_VERSION_RE = re.compile(
    r"^(?P<major>0|[1-9]\d*)\.(?P<minor>0|[1-9]\d*)\.(?P<patch>0|[1-9]\d*)"
    r"(?:-(?P<prerelease>(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)"
    r"(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?"
    r"(?:\+(?P<build>[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$"
)

_NUMERIC_RE = re.compile(r"^(?:0|[1-9]\d*)$")
_NUMERIC_ONLY_RE = re.compile(r"^\d+$")


class Version:
    __slots__ = ("major", "minor", "patch", "prerelease", "build")

    def __init__(self, major, minor, patch, prerelease=(), build=()):
        self.major = int(major)
        self.minor = int(minor)
        self.patch = int(patch)
        self.prerelease = tuple(prerelease)
        self.build = tuple(build)

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise ValueError("version must be a string")
        match = _VERSION_RE.match(text)
        if match is None:
            raise ValueError("invalid semantic version: %r" % (text,))
        prerelease = match.group("prerelease")
        build = match.group("build")
        return cls(
            int(match.group("major")),
            int(match.group("minor")),
            int(match.group("patch")),
            tuple(prerelease.split(".")) if prerelease is not None else (),
            tuple(build.split(".")) if build is not None else (),
        )

    def __str__(self):
        text = "%d.%d.%d" % (self.major, self.minor, self.patch)
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text

    def __repr__(self):
        return "Version(%r)" % (str(self),)

    def _key(self):
        if self.prerelease:
            prerelease = tuple(
                (0, int(ident), "") if _NUMERIC_ONLY_RE.match(ident) else (1, 0, ident)
                for ident in self.prerelease
            )
            return (self.major, self.minor, self.patch, 0, prerelease)
        return (self.major, self.minor, self.patch, 1, ())

    def _compare(self, other):
        key, other_key = self._key(), other._key()
        if key < other_key:
            return -1
        if key > other_key:
            return 1
        return 0

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) == 0

    def __ne__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) != 0

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) < 0

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) <= 0

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) > 0

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) >= 0

    def __hash__(self):
        return hash(self._key())

    def bump(self, kind):
        if kind == "major":
            return Version(self.major + 1, 0, 0)
        if kind == "minor":
            return Version(self.major, self.minor + 1, 0)
        if kind == "patch":
            return Version(self.major, self.minor, self.patch + 1)
        raise ValueError("invalid bump kind: %r" % (kind,))


def _parse_partial(text, allow_prerelease=False):
    if not isinstance(text, str) or text == "":
        raise ValueError("invalid version range: %r" % (text,))
    if "-" in text or "+" in text:
        if not allow_prerelease:
            raise ValueError(
                "partial version cannot have pre-release or build: %r" % (text,)
            )
        return Version.parse(text)
    parts = text.split(".")
    if len(parts) > 3:
        raise ValueError("invalid version range: %r" % (text,))
    numbers = []
    for part in parts:
        if not _NUMERIC_RE.match(part):
            raise ValueError("invalid version range: %r" % (text,))
        numbers.append(int(part))
    while len(numbers) < 3:
        numbers.append(0)
    return Version(*numbers)


def _parse_comparator(text):
    for operator in (">=", "<=", ">", "<", "="):
        if text.startswith(operator):
            return operator, _parse_partial(
                text[len(operator):], allow_prerelease=True
            )
    return "=", _parse_partial(text)


def _caret_bounds(version):
    lower = version
    if version.major != 0:
        upper = Version(version.major + 1, 0, 0)
    elif version.minor != 0:
        upper = Version(0, version.minor + 1, 0)
    else:
        upper = Version(0, 0, version.patch + 1)
    return ">=", lower, "<", upper


def _tilde_bounds(version):
    lower = version
    if version.minor != 0 or version.patch != 0:
        upper = Version(version.major, version.minor + 1, 0)
    else:
        upper = Version(version.major + 1, 0, 0)
    return ">=", lower, "<", upper


def _parse_spec(spec):
    if not isinstance(spec, str):
        raise ValueError("version range must be a string")
    comparators = spec.split()
    if not comparators:
        raise ValueError("empty version range")
    constraints = []
    for text in comparators:
        if text.startswith("^"):
            constraints.append(_caret_bounds(_parse_partial(text[1:])))
        elif text.startswith("~"):
            constraints.append(_tilde_bounds(_parse_partial(text[1:])))
        else:
            operator, version = _parse_comparator(text)
            constraints.append((operator, version))
    return constraints


def satisfies(version, spec):
    constraints = _parse_spec(spec)
    if isinstance(version, str):
        version = Version.parse(version)
    elif not isinstance(version, Version):
        raise ValueError("version must be a Version or a string")
    for operator, bound in constraints:
        if operator == "=":
            ok = version == bound
        elif operator == ">":
            ok = version > bound
        elif operator == ">=":
            ok = version >= bound
        elif operator == "<":
            ok = version < bound
        else:
            ok = version <= bound
        if not ok:
            return False
    return True
