"""Business-day arithmetic on datetime.date values."""

from __future__ import annotations

from datetime import date, timedelta
from typing import Iterable

__all__ = ["is_business_day", "business_days_between", "add_business_days"]

_DEFAULT_WEEKEND = (5, 6)


def _validate(
    holidays: Iterable[date], weekend: Iterable[int]
) -> tuple[frozenset[int], frozenset[date]]:
    """Normalize and validate the weekend/holiday parameters.

    Returns a (weekend, holidays) pair of frozensets. Raises ValueError if
    weekend is invalid or leaves no working day.
    """
    wk = []
    for w in weekend:
        if not isinstance(w, int) or isinstance(w, bool) or not 0 <= w <= 6:
            raise ValueError("weekend must contain integers from 0 to 6")
        wk.append(w)
    wk_set = frozenset(wk)
    if len(wk_set) >= 7:
        raise ValueError("weekend must leave at least one working day")
    hol = frozenset(holidays)
    return wk_set, hol


def is_business_day(
    d: date, *, holidays: Iterable[date] = (), weekend: Iterable[int] = _DEFAULT_WEEKEND
) -> bool:
    """Return True if d is neither on a weekend weekday nor a holiday."""
    wk, hol = _validate(holidays, weekend)
    return d.weekday() not in wk and d not in hol


def business_days_between(
    start: date,
    end: date,
    *,
    include_start: bool = True,
    include_end: bool = False,
    holidays: Iterable[date] = (),
    weekend: Iterable[int] = _DEFAULT_WEEKEND,
) -> int:
    """Count business days in [start, end] honoring the inclusion flags."""
    if start > end:
        raise ValueError("start must not be after end")
    wk, hol = _validate(holidays, weekend)

    total = 0
    if include_start and start.weekday() not in wk and start not in hol:
        total += 1
    if include_end and end.weekday() not in wk and end not in hol:
        total += 1

    days = (end - start).days
    if days > 1:
        d = start + timedelta(days=1)
        last = end - timedelta(days=1)
        while d <= last:
            if d.weekday() not in wk and d not in hol:
                total += 1
            d += timedelta(days=1)
    return total


def _next_business_day(d: date, wk: frozenset[int], hol: frozenset[date]) -> date:
    d = d + timedelta(days=1)
    while d.weekday() in wk or d in hol:
        d += timedelta(days=1)
    return d


def _prev_business_day(d: date, wk: frozenset[int], hol: frozenset[date]) -> date:
    d = d - timedelta(days=1)
    while d.weekday() in wk or d in hol:
        d -= timedelta(days=1)
    return d


def add_business_days(
    d: date, n: int, *, holidays: Iterable[date] = (), weekend: Iterable[int] = _DEFAULT_WEEKEND
) -> date:
    """Return the date n business days away from d (d itself never counted)."""
    wk, hol = _validate(holidays, weekend)

    if n > 0:
        for _ in range(n):
            d = _next_business_day(d, wk, hol)
        return d
    if n < 0:
        for _ in range(-n):
            d = _prev_business_day(d, wk, hol)
        return d
    while d.weekday() in wk or d in hol:
        d += timedelta(days=1)
    return d
