"""Prefix autocomplete backed by a trie."""


class _Node:
    __slots__ = ("children", "word", "weight")

    def __init__(self) -> None:
        self.children: dict[str, "_Node"] = {}
        self.word: str | None = None
        self.weight: float = 0.0


class Autocomplete:
    def __init__(self) -> None:
        self._root = _Node()
        self._size = 0

    def add(self, word: str, weight: float = 1) -> None:
        if not word:
            raise ValueError("word must be non-empty")
        key = word.casefold()
        node = self._root
        for ch in key:
            node = node.children.setdefault(ch, _Node())
        if node.word is None:
            self._size += 1
        node.word = word
        node.weight = weight

    def delete(self, word: str) -> bool:
        key = word.casefold()
        nodes = [self._root]
        node = self._root
        for ch in key:
            node = node.children.get(ch)
            if node is None:
                return False
            nodes.append(node)
        if node.word is None:
            return False
        node.word = None
        node.weight = 0.0
        self._size -= 1
        for i in range(len(key) - 1, -1, -1):
            child = nodes[i + 1]
            if child.children or child.word is not None:
                break
            del nodes[i].children[key[i]]
        return True

    def complete(self, prefix: str, k: int = 10) -> list[str]:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        node = self._root
        for ch in prefix.casefold():
            node = node.children.get(ch)
            if node is None:
                return []
        results: list[tuple[float, str, str]] = []
        stack = [node]
        while stack:
            current = stack.pop()
            if current.word is not None:
                results.append(
                    (-current.weight, current.word.casefold(), current.word)
                )
            stack.extend(current.children.values())
        results.sort()
        return [word for _, _, word in results[:k]]

    def __contains__(self, word: str) -> bool:
        node = self._root
        for ch in str(word).casefold():
            node = node.children.get(ch)
            if node is None:
                return False
        return node.word is not None

    def __len__(self) -> int:
        return self._size
