"""Prefix autocomplete backed by a trie."""

from __future__ import annotations

from typing import Iterator, Optional


class _Node:
    __slots__ = ("children", "word", "weight")

    def __init__(self) -> None:
        self.children: dict[str, _Node] = {}
        self.word: Optional[str] = None
        self.weight: float = 0.0


class Autocomplete:
    """Stores weighted words and suggests them for a typed prefix."""

    def __init__(self) -> None:
        self._root = _Node()
        self._size = 0

    def __len__(self) -> int:
        return self._size

    def __contains__(self, word: object) -> bool:
        if not isinstance(word, str):
            return False
        return self._find(word) is not None

    def add(self, word: str, weight: float = 1) -> None:
        if not word:
            raise ValueError("word must be a non-empty string")
        key = word.casefold()
        node = self._root
        for ch in key:
            node = node.children.setdefault(ch, _Node())
        if node.word is None:
            self._size += 1
        node.word = word
        node.weight = float(weight)

    def delete(self, word: str) -> bool:
        key = word.casefold()
        path: list[tuple[_Node, str]] = []
        node = self._root
        for ch in key:
            nxt = node.children.get(ch)
            if nxt is None:
                return False
            path.append((node, ch))
            node = nxt
        if node.word is None:
            return False
        node.word = None
        self._size -= 1
        for parent, ch in reversed(path):
            child = parent.children[ch]
            if child.children or child.word is not None:
                break
            del parent.children[ch]
        return True

    def complete(self, prefix: str, k: int = 10) -> list[str]:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        node = self._root
        for ch in prefix.casefold():
            node = node.children.get(ch)
            if node is None:
                return []
        results = sorted(self._iter_words(node), key=lambda e: (e[2], e[0]))
        results.reverse()
        return [entry[1] for entry in results[:k]]

    def _find(self, word: str) -> Optional[_Node]:
        node = self._root
        for ch in word.casefold():
            node = node.children.get(ch)
            if node is None:
                return None
        return node if node.word is not None else None

    def _iter_words(self, node: _Node) -> Iterator[tuple[str, str, float]]:
        """Yield (casefolded, original, weight) for words under ``node``."""
        if node.word is not None:
            yield (node.word.casefold(), node.word, node.weight)
        for child in node.children.values():
            yield from self._iter_words(child)
