def first_index(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    if lo < len(a) and a[lo] == x:
        return lo
    return -1


def last_index(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] <= x:
            lo = mid + 1
        else:
            hi = mid
    i = lo - 1
    if i >= 0 and a[i] == x:
        return i
    return -1


def insertion_point(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo


def count(a, x):
    return last_index(a, x) - first_index(a, x) + 1


def rotation_offset(a):
    if not a:
        raise ValueError("empty list")
    lo, hi = 0, len(a) - 1
    if a[lo] <= a[hi]:
        return 0
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] > a[hi]:
            lo = mid + 1
        else:
            hi = mid
    return lo


def search_rotated(a, x):
    n = len(a)
    if n == 0:
        return -1
    if a[0] <= a[-1]:
        return first_index(a, x)
    lo, hi = 0, n - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == x:
            return mid
        if a[lo] <= a[mid]:
            if a[lo] <= x < a[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if a[mid] < x <= a[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1


def isqrt(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("isqrt() argument must be nonnegative")
    if n < 2:
        return n
    bit = 1 << ((n.bit_length() - 2) & ~1)
    x = 0
    while bit:
        t = x + bit
        if t * t <= n:
            x = t
        bit >>= 2
    return x
