"""Binary-search utilities. All operations run in O(log n) time."""


def first_index(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    if lo < len(a) and a[lo] == x:
        return lo
    return -1


def last_index(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] <= x:
            lo = mid + 1
        else:
            hi = mid
    p = lo - 1
    if p >= 0 and a[p] == x:
        return p
    return -1


def insertion_point(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo


def count(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    first = lo
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] <= x:
            lo = mid + 1
        else:
            hi = mid
    return lo - first


def search_rotated(a, x):
    n = len(a)
    if n == 0:
        return -1
    if n == 1:
        return 0 if a[0] == x else -1
    lo, hi = 0, n - 1
    while True:
        if lo == hi:
            return lo if a[lo] == x else -1
        mid = (lo + hi) // 2
        nxt = mid + 1
        if a[mid] > a[nxt]:
            if x == a[mid]:
                return mid
            if a[lo] <= x:
                hi = mid
            else:
                lo = nxt
        else:
            if a[lo] <= x <= a[mid]:
                hi = mid
            else:
                lo = nxt


def rotation_offset(a):
    if not a:
        raise ValueError("empty list")
    lo, hi = 0, len(a) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] > a[hi]:
            lo = mid + 1
        else:
            hi = mid
    return lo


def isqrt(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("isqrt() argument must be nonnegative")
    if n == 0:
        return 0
    bits = n.bit_length()
    lo, hi = 1 << ((bits - 1) // 2), 1 << ((bits + 2) // 2)
    while True:
        mid = (lo + hi + 1) // 2
        sq = mid * mid
        if sq == n:
            return mid
        if sq < n:
            if (mid + 1) * (mid + 1) > n:
                return mid
            lo = mid
        else:
            if sq - mid <= n:
                return mid - 1
            hi = mid - 1
