"""Exact money arithmetic in cents using decimal.Decimal."""

from decimal import Decimal, InvalidOperation, ROUND_DOWN, ROUND_HALF_EVEN, localcontext
from typing import Union

Number = Union[int, Decimal, str]

_TWO_PLACES = Decimal("0.01")


def to_cents(x: Number) -> Decimal:
    if isinstance(x, bool) or isinstance(x, float):
        raise TypeError(f"unsupported type: {type(x).__name__}")
    if isinstance(x, int):
        d = Decimal(x)
    elif isinstance(x, Decimal):
        d = x
    elif isinstance(x, str):
        try:
            d = Decimal(x.strip())
        except InvalidOperation:
            raise ValueError(f"not a finite decimal number: {x!r}") from None
    else:
        raise TypeError(f"unsupported type: {type(x).__name__}")
    if not d.is_finite():
        raise ValueError(f"not a finite decimal number: {x!r}")
    return d.quantize(_TWO_PLACES, rounding=ROUND_HALF_EVEN)


def _validate_ratio(r) -> Decimal:
    if isinstance(r, bool) or isinstance(r, float):
        raise ValueError(f"invalid ratio: {r!r}")
    if isinstance(r, int):
        d = Decimal(r)
    elif isinstance(r, Decimal):
        d = r
    else:
        raise ValueError(f"invalid ratio: {r!r}")
    if not d.is_finite() or d < 0:
        raise ValueError(f"invalid ratio: {r!r}")
    return d


def allocate(amount: Number, ratios: list) -> list[Decimal]:
    value = to_cents(amount)
    if not ratios:
        raise ValueError("ratios must be a non-empty list")
    weights = [_validate_ratio(r) for r in ratios]
    total = sum(weights, Decimal(0))
    if total <= 0:
        raise ValueError("sum of ratios must be positive")

    negative = value < 0
    cents = int(abs(value).scaleb(2))

    base = [0] * len(weights)
    remainders = []
    with localcontext() as ctx:
        ctx.prec = 10000
        for i, w in enumerate(weights):
            exact = Decimal(cents) * w / total
            floor_share = int(exact.to_integral_value(rounding=ROUND_DOWN))
            base[i] = floor_share
            remainders.append(exact - Decimal(floor_share))

    leftover = cents - sum(base)
    order = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
    for i in range(leftover):
        base[order[i]] += 1

    result = [Decimal(part).scaleb(-2).quantize(_TWO_PLACES) for part in base]
    if negative:
        result = [-p for p in result]
    return result


def split_even(amount: Number, n: int) -> list[Decimal]:
    if n < 1:
        raise ValueError("n must be at least 1")
    return allocate(amount, [1] * n)


def format_money(amount: Number) -> str:
    value = to_cents(amount)
    sign = "-" if value < 0 else ""
    digits = abs(value).quantize(_TWO_PLACES)
    cents = int(digits.scaleb(2))
    whole, frac = divmod(cents, 100)
    whole_str = f"{whole:,}"
    return f"{sign}{whole_str}.{frac:02d}"
