import money
from decimal import Decimal


def test_to_cents_rounding():
    assert money.to_cents("2.675") == Decimal("2.68")
    assert money.to_cents("2.665") == Decimal("2.66")
    assert money.to_cents(5) == Decimal("5.00")
    assert money.to_cents(Decimal("1.005")) == Decimal("1.00")
    assert money.to_cents("  10.005  ") == Decimal("10.00")
    assert money.to_cents(-2.675) == Decimal("-2.68")


def test_to_cents_exponent():
    assert money.to_cents(5).as_tuple().exponent == -2


def test_to_cents_type_errors():
    for bad in [1.0, True, False, None, [1], (1,), object()]:
        try:
            money.to_cents(bad)
        except TypeError:
            pass
        else:
            raise AssertionError(f"no TypeError for {bad!r}")


def test_to_cents_errors():
    for bad in ["NaN", "Infinity", "-Infinity", "abc", "", "1.2.3", "1e", "0x10"]:
        try:
            money.to_cents(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"no ValueError for {bad!r}")
    for bad in [Decimal("NaN"), Decimal("Infinity")]:
        try:
            money.to_cents(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"no ValueError for {bad!r}")


def test_allocate_examples():
    assert money.allocate("100", [1, 1, 1]) == [
        Decimal("33.34"), Decimal("33.33"), Decimal("33.33")
    ]
    assert money.allocate("0.05", [3, 7]) == [Decimal("0.02"), Decimal("0.03")]


def test_allocate_sums():
    cases = [
        ("1.00", [1, 1, 1]),
        ("0.01", [1, 1, 1]),
        ("10.00", [1, 2, 3, 4]),
        ("-10.00", [1, 2, 3]),
        ("100.00", [Decimal("0.5"), Decimal("0.5")]),
        ("1000.01", [3, 7]),
        ("1234.56", [Decimal("0.333"), Decimal("0.333"), Decimal("0.334")]),
        ("-0.05", [3, 7]),
        ("99999999999999999.99", [7, 11, 13]),
        ("0.01", [Decimal("1"), Decimal("2"), Decimal("3")]),
    ]
    for amount, ratios in cases:
        parts = money.allocate(amount, ratios)
        assert sum(parts) == money.to_cents(amount), (amount, ratios, parts)
        assert len(parts) == len(ratios)
        for p in parts:
            assert p.as_tuple().exponent == -2


def test_allocate_tie_break():
    assert money.allocate("0.03", [1, 1, 1]) == [
        Decimal("0.01"), Decimal("0.01"), Decimal("0.01")
    ]
    assert money.allocate("0.01", [1, 1]) == [Decimal("0.01"), Decimal("0.00")]


def test_allocate_negative_symmetry():
    pos = money.allocate("10.00", [1, 2])
    neg = money.allocate("-10.00", [1, 2])
    assert neg == [-p for p in pos]


def test_allocate_errors():
    for ratios in [[], [0, 0], [-1, 2], [1.5, 1], [True], ["a"], [Decimal("NaN")]]:
        try:
            money.allocate("10", ratios)
        except ValueError:
            pass
        else:
            raise AssertionError(f"no ValueError for {ratios!r}")


def test_allocate_zero():
    assert money.allocate("0", [1, 2, 3]) == [Decimal("0.00")] * 3
    assert money.allocate("-0", [1, 2, 3]) == [Decimal("0.00")] * 3
    assert money.allocate("-0.001", [1, 2, 3]) == [Decimal("0.00")] * 3


def test_split_even():
    assert money.split_even("1.00", 3) == [
        Decimal("0.34"), Decimal("0.33"), Decimal("0.33")
    ]
    assert money.split_even("10", 4) == [Decimal("2.50")] * 4
    try:
        money.split_even("1", 0)
    except ValueError:
        pass
    else:
        raise AssertionError("no ValueError for n=0")
    try:
        money.split_even("1", -1)
    except ValueError:
        pass
    else:
        raise AssertionError("no ValueError for n=-1")


def test_format_money():
    assert money.format_money("-1234567.891") == "-1,234,567.89"
    assert money.format_money("-0.001") == "0.00"
    assert money.format_money("0") == "0.00"
    assert money.format_money(1234567) == "1,234,567.00"
    assert money.format_money("0.1") == "0.10"
    assert money.format_money("-1000") == "-1,000.00"
    assert money.format_money("999.99") == "999.99"
    assert money.format_money("1000.005") == "1,000.00"
    assert money.format_money("-0.005") == "0.00"
    assert money.format_money("-0.006") == "-0.01"
    assert money.format_money("1000000") == "1,000,000.00"


if __name__ == "__main__":
