from dataclasses import dataclass
from typing import Any, Callable, Optional


class MachineError(Exception):
    pass


class InvalidTransition(MachineError):
    def __init__(self, state: str, event: str):
        super().__init__(
            f"no transition for event {event!r} from state {state!r}"
        )
        self.state = state
        self.event = event


class GuardRejected(MachineError):
    def __init__(self, state: str, event: str):
        super().__init__(
            f"all transitions for event {event!r} from state {state!r} "
            "were rejected by their guards"
        )
        self.state = state
        self.event = event


@dataclass
class State:
    name: str
    on_enter: Optional[Callable] = None
    on_exit: Optional[Callable] = None


@dataclass
class Transition:
    event: str
    source: Any
    target: Any
    guard: Optional[Callable] = None
    action: Optional[Callable] = None


@dataclass
class Event:
    name: str
    source: str
    target: str
    data: dict


class Machine:
    def __init__(self, states, transitions, initial: str, context=None):
        if not states:
            raise ValueError("states must not be empty")
        self._states: dict[str, State] = {}
        for item in states:
            st = State(item) if isinstance(item, str) else item
            if st.name in self._states:
                raise ValueError(f"duplicate state name {st.name!r}")
            self._states[st.name] = st
        if initial not in self._states:
            raise ValueError(f"initial state {initial!r} is not a known state")
        for t in transitions:
            if t.source != "*":
                names = t.source if isinstance(t.source, (list, tuple)) else [t.source]
                for name in names:
                    if name not in self._states:
                        raise ValueError(
                            f"transition {t.event!r} names unknown source {name!r}"
                        )
            if t.target is not None and t.target not in self._states:
                raise ValueError(
                    f"transition {t.event!r} names unknown target {t.target!r}"
                )
        self._transitions = list(transitions)
        self._initial = initial
        self.state = initial
        self.context = context
        self.history: list[tuple] = []
        self._listeners: list[Callable] = []
        self._firing = False

    def _matches(self, t: Transition, state: str) -> bool:
        if t.source == "*":
            return True
        if isinstance(t.source, (list, tuple)):
            return state in t.source
        return t.source == state

    def _candidates(self, event: str) -> list[Transition]:
        return [
            t for t in self._transitions if t.event == event and self._matches(t, self.state)
        ]

    def fire(self, event: str, **data) -> str:
        if self._firing:
            raise MachineError("fire called while a transition is in progress")
        self._firing = True
        try:
            candidates = self._candidates(event)
            if not candidates:
                raise InvalidTransition(self.state, event)
            shared = data
            chosen = None
            for t in candidates:
                probe = Event(event, self.state, self.state if t.target is None else t.target, shared)
                if t.guard is None or t.guard(self, probe):
                    chosen = t
                    break
            if chosen is None:
                raise GuardRejected(self.state, event)
            source = self.state
            if chosen.target is None:
                ev = Event(event, source, source, shared)
                if chosen.action is not None:
                    chosen.action(self, ev)
                self.history.append((source, event, source))
                for listener in self._listeners:
                    listener(source, event, source)
            else:
                target = chosen.target
                ev = Event(event, source, target, shared)
                source_state = self._states[source]
                if source_state.on_exit is not None:
                    source_state.on_exit(self, ev)
                if chosen.action is not None:
                    chosen.action(self, ev)
                self.state = target
                self.history.append((source, event, target))
                target_state = self._states[target]
                if target_state.on_enter is not None:
                    target_state.on_enter(self, ev)
                for listener in self._listeners:
                    listener(source, event, target)
        finally:
            self._firing = False
        return self.state

    def can_fire(self, event: str, **data) -> bool:
        candidates = self._candidates(event)
        if not candidates:
            return False
        shared = data
        for t in candidates:
            probe = Event(event, self.state, self.state if t.target is None else t.target, shared)
            if t.guard is None or t.guard(self, probe):
                return True
        return False

    def available_events(self) -> list[str]:
        names = {t.event for t in self._transitions if self._matches(t, self.state)}
        return sorted(names)

    def on_transition(self, listener: Callable) -> None:
        self._listeners.append(listener)

    def reset(self) -> None:
        self.state = self._initial
        self.history.clear()
