from typing import Optional

import fsm


class VendingError(Exception):
    pass


class SoldOut(VendingError):
    pass


class InsufficientCredit(VendingError):
    pass


COINS = (5, 10, 25, 100)


def _change(amount: int) -> list[int]:
    coins: list[int] = []
    for coin in (100, 25, 10, 5):
        while amount >= coin:
            coins.append(coin)
            amount -= coin
    return coins


class VendingMachine:
    def __init__(self, products: dict[str, tuple[int, int]]):
        self._stock: dict[str, int] = {code: stock for code, (price, stock) in products.items()}
        self._price: dict[str, int] = {code: price for code, (price, stock) in products.items()}
        self._credit = 0
        self._sold: dict[str, int] = {}
        self._revenue = 0
        self._coin = 0
        self._change: list[int] = []
        self._restock_args: tuple = ()        states = [
            fsm.State("idle"),
            fsm.State("credit"),
            fsm.State("maintenance"),
        ]
        transitions = [
            fsm.Transition("insert", ["idle", "credit"], "credit", action=_add_coin),
            fsm.Transition("select", "credit", "idle", action=_sell),
            fsm.Transition("cancel", "credit", "idle", action=_refund),
            fsm.Transition("service", "idle", "maintenance"),
            fsm.Transition("restock", "maintenance", "maintenance", action=_restock),
            fsm.Transition("resume", "maintenance", "idle"),
        ]
        self.machine = fsm.Machine(states, transitions, initial="idle", context=self)

    @property
    def state(self) -> str:
        return self.machine.state

    @property
    def credit(self) -> int:
        return self._credit

    def stock(self, code: str) -> int:
        if code not in self._stock:
            raise KeyError(code)
        return self._stock[code]

    def price(self, code: str) -> int:
        if code not in self._price:
            raise KeyError(code)
        return self._price[code]

    def sales(self) -> dict[str, int]:
        return dict(self._sold)

    @property
    def revenue(self) -> int:
        return self._revenue

    def insert(self, coin: int) -> int:
        if coin not in COINS:
            raise ValueError(f"coin {coin!r} is not accepted")
        self._coin = coin
        self.machine.fire("insert", coin=coin)
        return self._credit

    def select(self, code: str) -> list[int]:
        price = self._price.get(code)
        if price is None:
            raise KeyError(code)
        if self._stock[code] <= 0:
            raise SoldOut(f"{code} is sold out")
        if self._credit < price:
            raise InsufficientCredit(
                f"credit {self._credit} is below price {price}"
            )
        self._change = _change(self._credit - price)
        self.machine.fire("select", code=code, price=price)
        return self._change

    def cancel(self) -> list[int]:
        coins = _change(self._credit)
        self.machine.fire("cancel", coins=coins)
        return coins

    def service(self) -> None:
        self.machine.fire("service")

    def restock(self, code: str, qty: int, price: Optional[int] = None) -> None:
        if qty < 1:
            raise ValueError("qty must be at least 1")
        if code not in self._price and price is None:
            raise KeyError(code)
        self._restock_args = (code, qty, price)
        self.machine.fire("restock")

    def resume(self) -> None:
        self.machine.fire("resume")


def _add_coin(machine, event) -> None:
    machine.context._credit += event.data["coin"]


def _sell(machine, event) -> None:
    vm = machine.context
    code = event.data["code"]
    price = event.data["price"]
    vm._stock[code] -= 1
    vm._sold[code] = vm._sold.get(code, 0) + 1
    vm._revenue += price
    vm._credit = 0


def _refund(machine, event) -> None:
    machine.context._credit = 0


def _restock(machine, event) -> None:
    vm = machine.context
    code, qty, price = vm._restock_args
    vm._stock[code] = vm._stock.get(code, 0) + qty
    if price is not None:
        vm._price[code] = price
