from .versions import Version, Range


class PackageIndex:
    def __init__(self):
        self._data = {}

    def add(self, name, version, requires=None):
        ver = Version(version)
        reqs = {}
        if requires:
            for dep_name, spec in requires.items():
                reqs[dep_name] = Range(spec)
        releases = self._data.setdefault(name, {})
        if ver in releases:
            raise ValueError(f"{name} {ver} is already in the index")
        releases[ver] = reqs

    def versions(self, name):
        releases = self._data.get(name)
        if not releases:
            return []
        return sorted(releases, reverse=True)

    def requirements(self, name, version):
        releases = self._data.get(name)
        if releases is None or version not in releases:
            raise KeyError(f"{name} {version} is not in the index")
        return dict(releases[version])

    @classmethod
    def from_dict(cls, data):
        index = cls()
        for name, releases in data.items():
            for version, requires in releases.items():
                index.add(name, version, requires)
        return index
