from .versions import Range


class ResolutionError(Exception):
    def __init__(self, package, explanation):
        super().__init__(explanation)
        self.package = package
        self.explanation = explanation


def _explain_failure(index, package, constraints, candidates, selected):
    lines = [f"cannot resolve {package}"]
    for requirer, range_ in constraints:
        lines.append(f"  {requirer} requires {package} {range_}")
    if not candidates:
        lines.append(f"  no versions of {package} are known")
        return lines
    for version in candidates:
        if not all(range_.contains(version) for _, range_ in constraints):
            lines.append(f"  {package} {version} is excluded by the constraints")
            continue
        conflict = None
        for dep, range_ in sorted(index.requirements(package, version).items()):
            if dep in selected and not range_.contains(selected[dep]):
                conflict = (
                    f"  {package} {version} requires {dep} {range_}, "
                    f"but {dep} {selected[dep]} is selected"
                )
                break
        if conflict is not None:
            lines.append(conflict)
        else:
            lines.append(f"  {package} {version} is excluded by the constraints")
    return lines


def resolve(index, requirements):
    root = {}
    for name, spec in requirements.items():
        try:
            root[name] = Range(spec)
        except ValueError as exc:
            raise ValueError(f"bad requirement for {name!r}: {exc}") from exc
    order = sorted(root)
    selected = {}
    failure = None

    def search():
        nonlocal failure
        target = next((name for name in order if name not in selected), None)
        if target is None:
            return dict(selected)

        constraints = []
        if target in root:
            constraints.append(("<root>", root[target]))
        for req_name, req_version in selected.items():
            reqs = index.requirements(req_name, req_version)
            if target in reqs:
                constraints.append((f"{req_name} {req_version}", reqs[target]))

        candidates = index.versions(target)

        def is_acceptable(version):
            if not all(range_.contains(version) for _, range_ in constraints):
                return False
            for dep, range_ in sorted(index.requirements(target, version).items()):
                if dep in selected and not range_.contains(selected[dep]):
                    return False
            return True

        acceptable = [v for v in candidates if is_acceptable(v)]

        if not acceptable:
            if failure is None:
                lines = _explain_failure(index, target, constraints, candidates, selected)
                failure = ResolutionError(target, "\n".join(lines))
            return None

        for candidate in acceptable:
            selected[target] = candidate
            deps = index.requirements(target, candidate)
            added = sorted(d for d in deps if d not in order)
            order.extend(added)
            result = search()
            if result is not None:
                return result
            for name in added:
                order.remove(name)
            del selected[target]
        return None

    result = search()
    if result is not None:
        return result
    raise failure
