import functools
import re


@functools.total_ordering
class Version:
    def __init__(self, text):
        if not isinstance(text, str):
            raise ValueError(f"invalid version: {text!r}")
        parts = text.split(".")
        if len(parts) != 3:
            raise ValueError(f"invalid version: {text!r}")
        numbers = []
        for part in parts:
            if not part or not part.isdigit() or (len(part) > 1 and part[0] == "0"):
                raise ValueError(f"invalid version: {text!r}")
            numbers.append(int(part))
        self.major, self.minor, self.patch = numbers
        self._text = f"{self.major}.{self.minor}.{self.patch}"

    def __str__(self):
        return self._text

    def __repr__(self):
        return f"Version({self._text!r})"

    def _key(self):
        return (self.major, self.minor, self.patch)

    def __eq__(self, other):
        if isinstance(other, Version):
            return self._key() == other._key()
        return NotImplemented

    def __lt__(self, other):
        if isinstance(other, Version):
            return self._key() < other._key()
        return NotImplemented

    def __hash__(self):
        return hash(self._key())


_CONSTRAINT_RE = re.compile(r"^\s*(!=|==|>=|<=|>|<|\^|~|\*)\s*(.*)$")


def _parse_constraint(text):
    text = text.strip()
    if not text:
        raise ValueError("empty constraint")
    match = _CONSTRAINT_RE.match(text)
    if match is None:
        raise ValueError(f"invalid constraint: {text!r}")
    op = match.group(1)
    rest = match.group(2).strip()
    if op == "*":
        if rest:
            raise ValueError(f"invalid constraint: {text!r}")
        return None
    if not rest:
        raise ValueError(f"invalid constraint: {text!r}")
    version = Version(rest)
    if op == "==":
        return lambda v: v == version
    if op == "!=":
        return lambda v: v != version
    if op == ">":
        return lambda v: v > version
    if op == ">=":
        return lambda v: v >= version
    if op == "<":
        return lambda v: v < version
    if op == "<=":
        return lambda v: v <= version
    if op == "^":
        if version.major != 0:
            upper = Version(f"{version.major + 1}.0.0")
        elif version.minor != 0:
            upper = Version(f"0.{version.minor + 1}.0")
        else:
            upper = Version(f"0.0.{version.patch + 1}")
        return lambda v: version <= v < upper
    if op == "~":
        upper = Version(f"{version.major}.{version.minor + 1}.0")
        return lambda v: version <= v < upper
    raise ValueError(f"invalid constraint: {text!r}")


class Range:
    def __init__(self, spec):
        if not isinstance(spec, str):
            raise ValueError(f"invalid range spec: {spec!r}")
        self._spec = spec
        constraints = []
        for part in spec.split(","):
            if not part.strip():
                raise ValueError("empty constraint")
            constraints.append(_parse_constraint(part))
        self._constraints = constraints

    @property
    def spec(self):
        return self._spec

    def __str__(self):
        return re.sub(r"\s+", "", self._spec)

    def __repr__(self):
        return f"Range({str(self)!r})"

    def contains(self, version):
        return all(c(version) for c in self._constraints)

    def __contains__(self, version):
        return self.contains(version)
