from .versions import Version, Range


class ResolutionError(Exception):
    def __init__(self, package, explanation):
        self.package = package
        self.explanation = explanation
        super().__init__(explanation)


def resolve(index, requirements):
    root_ranges = {name: Range(spec) for name, spec in requirements.items()}
    order = sorted(root_ranges.keys())
    selected_order = []
    selected = {}
    failure = None

    def constraints_on(pkg):
        constraints = []
        if pkg in root_ranges:
            constraints.append(("<root>", root_ranges[pkg]))
        for name in selected_order:
            reqs = index.requirements(name, selected[name])
            if pkg in reqs:
                constraints.append((f"{name} {selected[name]}", reqs[pkg]))
        return constraints

    def search():
        nonlocal failure
        pkg = next((n for n in order if n not in selected), None)
        if pkg is None:
            return True

        constraints = constraints_on(pkg)
        for cand in index.versions(pkg):
            if any(cand not in rng for _, rng in constraints):
                continue
            reqs = index.requirements(pkg, cand)
            if any(dep in selected and selected[dep] not in rng for dep, rng in reqs.items()):
                continue

            selected[pkg] = cand
            selected_order.append(pkg)
            added = [d for d in sorted(reqs) if d not in order]
            order.extend(added)
            if search():
                return True
            for d in reversed(added):
                order.remove(d)
            selected_order.pop()
            del selected[pkg]

        if failure is None:
            failure = _explain(pkg, constraints)
        return False

    def _explain(pkg, constraints):
        lines = [f"cannot resolve {pkg}"]
        for requirer, rng in constraints:
            lines.append(f"  {requirer} requires {pkg} {rng}")
        versions = index.versions(pkg)
        if not versions:
            lines.append(f"  no versions of {pkg} are known")
        else:
            for ver in versions:
                if any(ver not in rng for _, rng in constraints):
                    lines.append(f"  {pkg} {ver} is excluded by the constraints")
                    continue
                reqs = index.requirements(pkg, ver)
                for dep in sorted(reqs):
                    if dep in selected and selected[dep] not in reqs[dep]:
                        lines.append(
                            f"  {pkg} {ver} requires {dep} {reqs[dep]}, "
                            f"but {dep} {selected[dep]} is selected"
                        )
                        break
        return ResolutionError(pkg, "\n".join(lines))

    if search():
        return dict(selected)
    raise failure
