    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._key() == other._key()

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._key() < other._key()

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._key() <= other._key()

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._key() > other._key()

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._key() >= other._key()

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

    def __repr__(self):
        return f"Version({str(self)!r})"


_CONSTRAINT_RE = re.compile(r"^\s*(\^|~|==|!=|>=|<=|>|<)?\s*(\*|\d+\.\d+\.\d+)\s*$")


class Range:
    def __init__(self, spec):
        self._spec = spec
        self._constraints = []
        if not isinstance(spec, str):
            raise ValueError(f"invalid range spec: {spec!r}")
        stripped = spec.strip()
        if not stripped:
            raise ValueError("empty range spec")
        for constraint in stripped.split(","):
            if not constraint.strip():
                raise ValueError("empty constraint in range spec")
            m = _CONSTRAINT_RE.match(constraint)
            if not m:
                raise ValueError(f"invalid constraint: {constraint.strip()!r}")
            op, ver = m.group(1), m.group(2)
            if op is None:
                op = "*" if ver == "*" else "=="
            self._constraints.append(self._make(op, ver))

    def _make(self, op, ver_text):
        if op == "*":
            return lambda v: True
        v = Version(ver_text)
        if op == "==":
            return lambda x: x == v
        if op == "!=":
            return lambda x: x != v
        if op == ">":
            return lambda x: x > v
        if op == ">=":
            return lambda x: x >= v
        if op == "<":
            return lambda x: x < v
        if op == "<=":
            return lambda x: x <= v
        if op == "^":
            lower = v
            if v.major != 0:
                upper = Version(f"{v.major + 1}.0.0")
            elif v.minor != 0:
                upper = Version(f"0.{v.minor + 1}.0")
            else:
                upper = Version(f"0.0.{v.patch + 1}")
            return lambda x: lower <= x < upper
        if op == "~":
            lower = v
            upper = Version(f"{v.major}.{v.minor + 1}.0")
            return lambda x: lower <= x < upper
        raise ValueError(f"unknown operator: {op!r}")

    def contains(self, v):
        return all(c(v) for c in self._constraints)

    def __contains__(self, v):
        return self.contains(v)

    def __str__(self):
        return re.sub(r"\s+", "", self._spec)

    def __repr__(self):
        return f"Range({str(self)!r})"
