import argparse
import json
import sys
from datetime import datetime, timezone

from .parsers import read_records
from .stats import filter_records, summarize


def _parse_time(text: str) -> datetime:
    value = text.strip()
    if value.endswith(("Z", "z")):
        value = value[:-1] + "+00:00"
    dt = datetime.fromisoformat(value)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(prog="logagg", description=__doc__)
    ap.add_argument("files", nargs="+", metavar="FILE")
    ap.add_argument("--format", default="auto", choices=("auto", "clf", "jsonl"))
    ap.add_argument("--since")
    ap.add_argument("--until")
    ap.add_argument("--status")
    ap.add_argument("--top", type=int, default=3)
    ap.add_argument("--json", action="store_true")
    args = ap.parse_args(argv)

    if args.top < 0:
        print("error: --top must be >= 0", file=sys.stderr)
        return 2

    records = []
    bad_lines = 0
    for path in args.files:
        try:
            with open(path, encoding="utf-8") as fh:
                chunk, bad = read_records(fh, args.format)
        except OSError as exc:
            print(f"error: cannot read {path}: {exc.strerror or exc}", file=sys.stderr)
            return 2
        records.extend(chunk)
        bad_lines += len(bad)

    try:
        since = _parse_time(args.since) if args.since else None
        until = _parse_time(args.until) if args.until else None
    except ValueError as exc:
        print(f"error: bad time: {exc}", file=sys.stderr)
        return 2

    try:
        records = filter_records(records, since, until, args.status)
    except ValueError as exc:
        print(f"error: bad status: {exc}", file=sys.stderr)
        return 2

    summary = summarize(records, args.top)

    if args.json:
        out = dict(summary)
        out["bad_lines"] = bad_lines
        print(json.dumps(out, indent=2))
    else:
        lines = [
            f"requests: {summary['requests']}",
            f"bad lines: {bad_lines}",
            f"bytes: {summary['bytes']}",
            "status: " + " ".join(f"{k}={v}" for k, v in summary["classes"].items()),
        ]
        lat = summary["latency_ms"]
        if lat["count"]:
            lines.append(
                f"latency: p50={lat['p50']:.1f} ms "
                f"p95={lat['p95']:.1f} ms max={lat['max']:.1f} ms"
            )
        else:
            lines.append("latency: n/a")
        lines.append("top paths:")
        if summary["top_paths"]:
            for path, count in summary["top_paths"]:
                lines.append(f"  {count} {path}")
        else:
            lines.append("  none")
        print("\n".join(lines))

    return 0


if __name__ == "__main__":
    sys.exit(main())
