import json
import re
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone


class ParseError(ValueError):
    pass


@dataclass(frozen=True)
class Record:
    time: datetime
    client: str
    method: str
    path: str
    status: int
    size: int
    latency_ms: float | None


def normalize(time, client, method, path, status, size, latency_ms) -> Record:
    if not isinstance(time, datetime) or time.tzinfo is None:
        raise ParseError("time must be a timezone-aware datetime")
    time = time.astimezone(timezone.utc)

    if not isinstance(client, str) or not client:
        raise ParseError("client must be a non-empty string")

    if not isinstance(method, str) or not method or not method.isascii() or not method.isalpha():
        raise ParseError("method must be a non-empty string of ASCII letters")
    method = method.upper()

    if not isinstance(path, str) or not path.startswith("/"):
        raise ParseError("path must start with /")
    path = re.split(r"[?#]", path, maxsplit=1)[0]
    path = re.sub(r"/+", "/", path)

    if isinstance(status, str):
        if not status.isdigit():
            raise ParseError("status must be a string of digits")
        status = int(status)
    elif not isinstance(status, int) or isinstance(status, bool):
        raise ParseError("status must be an int")
    if not 100 <= status <= 599:
        raise ParseError("status must be between 100 and 599")

    if size is None or size == "-":
        size = 0
    elif isinstance(size, str):
        if not size.isdigit():
            raise ParseError("size must be a string of digits")
        size = int(size)
    elif not isinstance(size, int) or isinstance(size, bool):
        raise ParseError("size must be an int")
    if size < 0:
        raise ParseError("size must be non-negative")

    if latency_ms is not None:
        if isinstance(latency_ms, bool) or not isinstance(latency_ms, (int, float)):
            raise ParseError("latency_ms must be a number")
        if latency_ms < 0:
            raise ParseError("latency_ms must be non-negative")
        latency_ms = float(latency_ms)

    return Record(time, client, method, path, status, size, latency_ms)


_MONTHS = {
    "Jan": 1, "Feb": 2, "Mar": 3, "Apr": 4, "May": 5, "Jun": 6,
    "Jul": 7, "Aug": 8, "Sep": 9, "Oct": 10, "Nov": 11, "Dec": 12,
}

_CLF_TIME_RE = re.compile(
    r"^(\d{2})/([A-Za-z]{3})/(\d{4}):(\d{2}):(\d{2}):(\d{2}) ([+-])(\d{2})(\d{2})$"
)


def _parse_clf_time(text: str) -> datetime:
    m = _CLF_TIME_RE.match(text)
    if not m:
        raise ParseError(f"invalid time: {text!r}")
    day, mon, year, hour, minute, sec, sign, offh, offm = m.groups()
    month = _MONTHS.get(mon.capitalize())
    if month is None:
        raise ParseError(f"invalid month: {mon!r}")
    off = timedelta(hours=int(offh), minutes=int(offm))
    if sign == "-":
        off = -off
    try:
        return datetime(
            int(year), month, int(day), int(hour), int(minute), int(sec),
            tzinfo=timezone(off),
        )
    except ValueError as exc:
        raise ParseError(f"invalid time: {text!r}") from exc


def _split_clf(line: str):
    rest = line
    client, sep, rest = rest.partition(" ")
    if not sep or not client:
        return None
    _ident, sep, rest = rest.partition(" ")
    if not sep:
        return None
    _user, sep, rest = rest.partition(" ")
    if not sep or not rest.startswith("["):
        return None
    close = rest.find("]")
    if close == -1:
        return None
    time_text = rest[1:close]
    if not time_text:
        return None
    rest = rest[close + 1:]
    if not rest.startswith(' "'):
        return None
    rest = rest[2:]
    quote = rest.find('"')
    if quote == -1:
        return None
    request = rest[:quote]
    rest = rest[quote + 1:]
    if not rest.startswith(" "):
        return None
    rest = rest[1:]
    fields = rest.split(" ")
    if len(fields) == 2:
        status, size = fields
        latency = None
    elif len(fields) == 3:
        status, size, latency = fields
    else:
        return None
    return client, time_text, request, status, size, latency


def parse_clf(line: str) -> Record:
    if "\n" in line or "\r" in line:
        raise ParseError(f"line does not match common log format: {line!r}")
    fields = _split_clf(line)
    if fields is None:
        raise ParseError(f"line does not match common log format: {line!r}")
    client, time_text, request, status, size, latency = fields
    parts = request.split(" ")
    if len(parts) != 3:
        raise ParseError(f"request line must have 3 parts: {line!r}")
    method, path, _proto = parts
    if latency is not None and not latency.isdigit():
        raise ParseError(f"invalid response time: {latency!r}")
    latency_ms = int(latency) / 1000 if latency is not None else None
    return normalize(
        _parse_clf_time(time_text),
        client,
        method,
        path,
        status,
        size,
        latency_ms,
    )


def parse_jsonl(line: str) -> Record:
    try:
        obj = json.loads(line)
    except (json.JSONDecodeError, ValueError) as exc:
        raise ParseError(f"invalid JSON: {line!r}") from exc
    if not isinstance(obj, dict):
        raise ParseError(f"JSON value is not an object: {line!r}")
    for key in ("ts", "client", "method", "path", "status"):
        if key not in obj:
            raise ParseError(f"missing key: {key!r}")

    ts = obj["ts"]
    if not isinstance(ts, str):
        raise ParseError("ts must be a string")
    text = ts.strip()
    if text.endswith(("Z", "z")):
        text = text[:-1] + "+00:00"
    try:
        time = datetime.fromisoformat(text)
    except ValueError as exc:
        raise ParseError(f"invalid ts: {ts!r}") from exc
    if time.tzinfo is None:
        raise ParseError(f"ts without an offset: {ts!r}")

    latency_ms = obj.get("latency_ms")
    if isinstance(latency_ms, str):
        try:
            latency_ms = float(latency_ms)
        except ValueError:
            raise ParseError(f"invalid latency_ms: {latency_ms!r}")

    return normalize(
        time,
        obj["client"],
        obj["method"],
        obj["path"],
        obj["status"],
        obj.get("bytes"),
        latency_ms,
    )


def parse_line(line: str, fmt: str = "auto") -> Record:
    if fmt == "auto":
        parser = parse_jsonl if line.lstrip().startswith("{") else parse_clf
    elif fmt == "clf":
        parser = parse_clf
    elif fmt == "jsonl":
        parser = parse_jsonl
    else:
        raise ValueError(f"unknown format: {fmt!r}")
    return parser(line)


def read_records(lines, fmt: str = "auto"):
    records = []
    bad = []
    for lineno, line in enumerate(lines, 1):
        if not line.strip():
            continue
        try:
            records.append(parse_line(line, fmt))
        except ParseError:
            bad.append(lineno)
    return records, bad
