import math
from collections import Counter


def percentile(values, p):
    values = list(values)
    if not values:
        raise ValueError("values must not be empty")
    if not 0 < p <= 100:
        raise ValueError("p must be in (0, 100]")
    ordered = sorted(values)
    rank = math.ceil(p / 100 * len(ordered))
    return ordered[rank - 1]


def filter_records(records, since=None, until=None, status=None):
    status_pred = None
    if status is not None:
        s = str(status)
        if len(s) == 3 and s[0] in "12345" and s[1:] == "xx":
            lo = int(s[0]) * 100
            status_pred = lambda code: lo <= code <= lo + 99  # noqa: E731
        elif s.isdigit():
            code = int(s)
            status_pred = lambda c: c == code  # noqa: E731
        else:
            raise ValueError(f"invalid status filter: {status!r}")

    out = []
    for r in records:
        if since is not None and r.time < since:
            continue
        if until is not None and not r.time < until:
            continue
        if status_pred is not None and not status_pred(r.status):
            continue
        out.append(r)
    return out


def summarize(records, top=3):
    if top < 0:
        raise ValueError("top must be >= 0")
    records = list(records)

    classes = {f"{k}xx": 0 for k in range(1, 6)}
    codes = Counter()
    counter = Counter()
    latencies = []
    first = None
    last = None
    total_bytes = 0

    for r in records:
        classes[f"{r.status // 100}xx"] += 1
        codes[str(r.status)] += 1
        counter[r.path] += 1
        total_bytes += r.size
        if r.latency_ms is not None:
            latencies.append(r.latency_ms)
        if first is None or r.time < first:
            first = r.time
        if last is None or r.time > last:
            last = r.time

    if latencies:
        latency = {
            "count": len(latencies),
            "p50": percentile(latencies, 50),
            "p95": percentile(latencies, 95),
            "max": max(latencies),
        }
    else:
        latency = {"count": 0, "p50": None, "p95": None, "max": None}

    top_paths = [
        [path, count]
        for path, count in sorted(counter.items(), key=lambda kv: (-kv[1], kv[0]))[:top]
    ]

    return {
        "requests": len(records),
        "bytes": total_bytes,
        "classes": classes,
        "codes": dict(sorted(codes.items(), key=lambda kv: int(kv[0]))),
        "latency_ms": latency,
        "top_paths": top_paths,
        "first": first.isoformat() if first is not None else None,
        "last": last.isoformat() if last is not None else None,
    }
